  class bad_typeid : public exception {
  public:
    bad_typeid() noexcept;  // Default constructor, typically inlined with no body or a simple vtable setup.
    bad_typeid(const bad_typeid&) noexcept;  // Copy constructor, often compiler-generated as a bitwise copy.
    bad_typeid& operator=(const bad_typeid&) noexcept;  // Assignment operator, also compiler-generated.
    virtual const char* what() const noexcept override;  // Virtual function returning a static string, implemented via vtable lookup.
  };
}
// Implementation notes: The noexcept specifier ensures no exceptions are thrown from these members, allowing the compiler to optimize by omitting try-catch blocks. The virtual what() implies a vtable, affecting object layout and dynamic dispatch at runtime.
